-- Categoria Financeira + status cancelado
alter table public.bcd_servicos drop constraint if exists bcd_servicos_categoria_check;
alter table public.bcd_servicos add constraint bcd_servicos_categoria_check check (categoria in ('iPhone','Android','Financeira','Operadora','Dados e sistema'));
alter table public.bcd_pedidos drop constraint if exists bcd_pedidos_status_check;
alter table public.bcd_pedidos add constraint bcd_pedidos_status_check check (status in ('novo','andamento','concluido','recusado','cancelado'));
-- Agenda
alter table public.bcd_pedidos add column if not exists agenda_data date, add column if not exists agenda_hora time;
create unique index if not exists bcd_pedidos_slot on public.bcd_pedidos (agenda_data, agenda_hora) where agenda_data is not null and status not in ('recusado','cancelado');
alter table public.bcd_config add column if not exists ag_ativo boolean not null default true,
  add column if not exists ag_abre int not null default 10 check (ag_abre between 0 and 23),
  add column if not exists ag_fecha int not null default 23 check (ag_fecha between 1 and 24),
  add column if not exists ag_intervalo int not null default 60 check (ag_intervalo in (15,20,30,45,60,90,120)),
  add column if not exists ag_dias int[] not null default '{0,1,2,3,4,5,6}',
  add column if not exists ag_janela int not null default 14 check (ag_janela between 1 and 60);
create table if not exists public.bcd_bloqueios (id bigint generated by default as identity primary key, data date not null, hora time, motivo text check (char_length(motivo) <= 80));
create unique index if not exists bcd_bloqueios_u on public.bcd_bloqueios (data, coalesce(hora, '23:59:59'::time));
alter table public.bcd_bloqueios enable row level security;
drop policy if exists "bcd bloq dono" on public.bcd_bloqueios; create policy "bcd bloq dono" on public.bcd_bloqueios for all to authenticated using (public.is_bcd_admin()) with check (public.is_bcd_admin());
revoke all on public.bcd_bloqueios from anon; grant select, insert, update, delete on public.bcd_bloqueios to authenticated;

create or replace function public.bcd_publico() returns json language sql stable security definer set search_path = public as $$
  select json_build_object(
   'servicos', coalesce((select json_agg(json_build_object('id',id,'categoria',categoria,'nome',nome,'descricao',descricao,'prazo',prazo,'preco',preco,'requisitos',requisitos,'icone',icone) order by ordem, id) from public.bcd_servicos where ativo), '[]'),
   'config', (select json_build_object('whatsapp',whatsapp,'aviso',aviso,'agenda',json_build_object('ativo',ag_ativo,'abre',ag_abre,'fecha',ag_fecha,'intervalo',ag_intervalo,'dias',ag_dias,'janela',ag_janela)) from public.bcd_config where id = 1),
   'hoje', to_char(now() at time zone 'America/Sao_Paulo','YYYY-MM-DD"T"HH24:MI'),
   'ocupados', coalesce((select json_agg(to_char(agenda_data,'YYYY-MM-DD')||' '||to_char(agenda_hora,'HH24:MI')) from public.bcd_pedidos
       where agenda_data >= (now() at time zone 'America/Sao_Paulo')::date and status not in ('recusado','cancelado')), '[]'),
   'bloqueios', coalesce((select json_agg(to_char(data,'YYYY-MM-DD')||coalesce(' '||to_char(hora,'HH24:MI'),'')) from public.bcd_bloqueios
       where data >= (now() at time zone 'America/Sao_Paulo')::date), '[]')) $$;

-- Confere se um horário pode ser agendado (usado pelo site).
create or replace function public.bcd_slot_ok(d date, h time) returns text language plpgsql stable security definer set search_path = public as $$
declare c public.bcd_config; agora timestamp := now() at time zone 'America/Sao_Paulo'; m int;
begin
  select * into c from public.bcd_config where id = 1;
  if d is null or h is null then return 'Escolha o dia e o horário.'; end if;
  if (d + h) <= agora then return 'Esse horário já passou. Escolha outro.'; end if;
  if d > agora::date + c.ag_janela then return 'Escolha um dia mais próximo.'; end if;
  if not (extract(dow from d)::int = any (c.ag_dias)) then return 'Não atendemos nesse dia da semana.'; end if;
  m := extract(hour from h)::int * 60 + extract(minute from h)::int;
  if m < c.ag_abre * 60 or m + c.ag_intervalo > c.ag_fecha * 60 or (m - c.ag_abre * 60) % c.ag_intervalo <> 0 then return 'Horário fora do atendimento.'; end if;
  if exists (select 1 from public.bcd_bloqueios where data = d and (hora is null or hora = h)) then return 'Esse horário não está disponível.'; end if;
  if exists (select 1 from public.bcd_pedidos where agenda_data = d and agenda_hora = h and status not in ('recusado','cancelado')) then return 'Esse horário acabou de ser reservado. Escolha outro.'; end if;
  return null;
end $$;
revoke all on function public.bcd_slot_ok(date, time) from public, anon, authenticated;

create or replace function public.bcd_pedir(p jsonb) returns json language plpgsql security definer set search_path = public as $$
declare tel text; r public.bcd_pedidos; d date; h time; e text;
begin
  tel := regexp_replace(coalesce(p->>'telefone',''),'\D','','g');
  if char_length(btrim(coalesce(p->>'nome',''))) < 2 then raise exception 'Informe seu nome.'; end if;
  if char_length(tel) < 10 or char_length(tel) > 13 then raise exception 'Informe um WhatsApp válido com DDD.'; end if;
  if (select count(*) from public.bcd_pedidos where created_at > now() - interval '1 minute') >= 15 then raise exception 'Muitas solicitações agora. Tente em um minuto.'; end if;
  if p ? 'agenda_data' then
    begin d := (p->>'agenda_data')::date; h := (p->>'agenda_hora')::time; exception when others then raise exception 'Escolha o dia e o horário.'; end;
    e := public.bcd_slot_ok(d, h); if e is not null then raise exception '%', e; end if;
  end if;
  begin
    insert into public.bcd_pedidos (nome, telefone, marca, modelo, servico, imei, detalhes, agenda_data, agenda_hora)
    values (left(btrim(p->>'nome'),80), tel, left(nullif(btrim(p->>'marca'),''),40), left(nullif(btrim(p->>'modelo'),''),60), left(nullif(btrim(p->>'servico'),''),100),
            left(nullif(regexp_replace(coalesce(p->>'imei',''),'\D','','g'),''),17), left(nullif(btrim(p->>'detalhes'),''),400), d, h) returning * into r;
  exception when unique_violation then raise exception 'Esse horário acabou de ser reservado. Escolha outro.'; end;
  return json_build_object('num', r.id);
end $$;
revoke all on function public.bcd_publico() from public; revoke all on function public.bcd_pedir(jsonb) from public;
grant execute on function public.bcd_publico() to anon, authenticated; grant execute on function public.bcd_pedir(jsonb) to anon, authenticated;

